import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringWriter hasil = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setHeader("id", "judul", "selesai")
                .build();
        try (CSVPrinter printer = new CSVPrinter(hasil, format)) {
            printer.printRecord(1, "Belajar CSV", false);
            printer.printRecord(2, "Rapat tim", true);
            printer.printRecord(3, "Beli kopi, gula", false);
            printer.printRecord(4, "Baca \"Clean Code\"", true);
            printer.printRecord(5, null, false);
        }
        System.out.print(hasil);

        List<Todo> daftar = Arrays.asList(new Todo(6, "Kirim laporan", false), new Todo(7, "Rapikan kode", true));
        StringWriter dariList = new StringWriter();
        try (CSVPrinter printer = new CSVPrinter(dariList, format)) {
            for (Todo t : daftar) {
                printer.printRecord(t.id, t.judul, t.selesai);
            }
        }
        System.out.print(dariList);
    }
}

class Todo {
    final int id;
    final String judul;
    final boolean selesai;

    Todo(int id, String judul, boolean selesai) {
        this.id = id;
        this.judul = judul;
        this.selesai = selesai;
    }
}

