import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    static final CSVFormat FORMAT = CSVFormat.DEFAULT.builder().setRecordSeparator("\n").build();

    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        StringWriter hasil = new StringWriter();
        try (CSVPrinter printer = new CSVPrinter(hasil, FORMAT)) {
            while (in.hasNextLine()) {
                String[] d = in.nextLine().split("\\|");
                printer.printRecord(d[0], d[1]);
            }
        }
        System.out.print(hasil);
    }
}
